-- --------------------------------------------------------
-- โครงสร้างตาราง: `products`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` varchar(100) NOT NULL,
  `name` varchar(255) NOT NULL,
  `nameTH` varchar(255) NOT NULL,
  `brand` varchar(100) NOT NULL,
  `category` varchar(100) NOT NULL,
  `subCategory` varchar(100) DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `stock` int(11) DEFAULT 50,
  `detail` text DEFAULT NULL,
  `originalPrice` decimal(10,2) DEFAULT NULL,
  `fdaNumber` varchar(100) NOT NULL,
  `rating` decimal(3,1) DEFAULT 5.0,
  `reviewsCount` int(11) DEFAULT 0,
  `servings` varchar(100) DEFAULT NULL,
  `size` varchar(100) DEFAULT NULL,
  `suitableFor` text DEFAULT NULL,
  `howToUse` text DEFAULT NULL,
  `goal` varchar(100) DEFAULT NULL,
  `badge` varchar(100) DEFAULT NULL,
  `inStock` int(11) DEFAULT 1,
  `imageUrl` varchar(255) DEFAULT NULL,
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ข้อมูลสำหรับตาราง `products`
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-creatine-5000', 'Baam!! 100% Creatine 5000 (Fitwhey)', 'แบม 100% ครีเอทีน 5000 ไมโครไนซ์ (เครือ Fitwhey)', 'Baam!! (Fitwhey)', 'creatine', 'Creatine Monohydrate', '690.00', 36, 'นักยกเวททุกระดับที่ต้องการเพิ่มพละกำลัง ยกหนักขึ้น กล้ามเนื้อฟูแน่น', '850.00', '10-3-08829-1-0027', '4.8', 2980, '60 เซิร์ฟวิ่ง', '300 กรัม', 'นักยกเวททุกระดับที่ต้องการเพิ่มพละกำลัง ยกหนักขึ้น กล้ามเนื้อฟูแน่น', 'ตัก 1 ช้อน (5g) ผสมกับน้ำเปล่า เวย์ หรือน้ำผลไม้ ดื่มทุกวัน วันละ 1 ครั้งเวลาใดก็ได้', 'strength', 'ครีเอทีนสุดคุ้มค่า Fitwhey', 1, '/images/products/baam-creatine.png', '[\"ครีเอทีนบริสุทธิ์ 5,000 มก.\",\"เกรดไมโครไนซ์อนุภาคละเอียด\",\"ทานได้ต่อเนื่องไม่ต้องหยุดรอบ\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-hydro-whey', 'Baam!! Hydro Whey Protein Isolate', 'แบม ไฮโดร เวย์ โปรตีน ไฮโดรไลซ์ ดูดซึมไว (4 ปอนด์)', 'Baam!! (Fitwhey)', 'whey', 'Hydrolyzed Whey (WPH)', '2360.00', 50, 'นักกีฬาที่ซ้อมหนักต้องการดูดซึมเข้ากล้ามเนื้อรวดเร็วที่สุด และผู้ที่ย่อยเวย์ทั่วไปยาก', '2690.00', '11-1-08463-5-0049', '4.9', 1180, '44 เซิร์ฟวิ่ง', '4 lbs (1.81 kg)', 'นักกีฬาที่ซ้อมหนักต้องการดูดซึมเข้ากล้ามเนื้อรวดเร็วที่สุด และผู้ที่ย่อยเวย์ทั่วไปยาก', 'ผสม 1 ช้อนตวงกับน้ำเย็น 250 มล. เขย่าให้ละลาย ดื่มทันทีหลังฝึกซ้อม', 'recovery', 'ไฮโดรไลซ์ดูดซึมไวพิเศษ', 1, '/images/products/baam-hydro-whey.webp', '[\"โปรตีน 30g ผ่านการย่อยโมเลกุลขนาดเล็ก\",\"BCAA 6g ต่อช้อน น้ำตาล 0g ไขมัน 0g\",\"ละลายน้ำง่าย ไม่เป็นก้อน สบายท้อง\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-intra-juice', 'Baam!! Intra Juice BCAA + Electrolytes', 'แบม อินทรา จูซ เครื่องดื่ม BCAA 7g และเกลือแร่ระหว่างซ้อม (30 เซิร์ฟวิ่ง)', 'Baam!! (Fitwhey)', 'pre-workout', 'Intra-Workout BCAA', '1125.00', 14, 'ผู้ที่ซ้อมเวทนานเกิน 60 นาที นักวิ่ง หรือคนที่เสียเหงื่อมากและต้องการลดการล้าระหว่างซ้อม', '1350.00', '11-1-08463-5-0129', '4.9', 1410, '30 เซิร์ฟวิ่ง', '30 เซิร์ฟวิ่ง', 'ผู้ที่ซ้อมเวทนานเกิน 60 นาที นักวิ่ง หรือคนที่เสียเหงื่อมากและต้องการลดการล้าระหว่างซ้อม', 'ผสม 1 ช้อนตวงกับน้ำเย็น 400-500 มล. จิบต่อเนื่องระหว่างออกกำลังกาย', 'endurance', 'BCAA 7g + เกลือแร่จิบระหว่างซ้อม', 1, '/images/products/baam-intra-juice.webp', '[\"BCAA เข้มข้น 7g ลดการสลายกล้ามเนื้อ\",\"L-Glutamine 2.5g เสริมการฟื้นฟู\",\"Electrolytes 800mg ชดเชยเกลือแร่ที่เสียไปกับเหงื่อ\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-iso-pea', 'Baam!! ISO Pea Protein Isolate', 'แบม ไอโซ พี โปรตีนถั่วลันเตาไอโซเลท ไร้นมและถั่วเหลือง (5 ปอนด์)', 'Baam!! (Fitwhey)', 'plant-protein', 'Pea Protein Isolate', '850.00', 50, 'ผู้ที่แพ้ทั้งนมวัวและถั่วเหลือง ชาววีแกน มังสวิรัติ และผู้ที่คุมแคลอรีแบบประหยัด', '1050.00', '11-1-08463-6-0033', '4.8', 1320, '60 เซิร์ฟวิ่ง', '5 lbs (2.27 kg)', 'ผู้ที่แพ้ทั้งนมวัวและถั่วเหลือง ชาววีแกน มังสวิรัติ และผู้ที่คุมแคลอรีแบบประหยัด', 'ผสม 1 ช้อนตวงกับน้ำเย็น 300 มล. เขย่าให้เข้ากัน ดื่มหลังซ้อมหรือทดแทนของว่าง', 'fat-loss', 'โปรตีนถั่วลันเตา 31g สุดคุ้ม', 1, '/images/products/baam-iso-pea.webp', '[\"โปรตีนถั่วลันเตาบริสุทธิ์ 31g ต่อช้อน\",\"ปราศจากนมวัว แลคโตส และถั่วเหลือง 100%\",\"BCAA 5.7g และ Glutamine 5.4g\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-iso-zero', 'Baam!! ISO Absolute Zero Whey Isolate', 'แบม ไอโซ แอบโซลูท ซีโร่ เวย์โปรตีนไอโซเลท (5 ปอนด์)', 'Baam!! (Fitwhey)', 'whey', 'Whey Isolate (WPI)', '3335.00', 4, 'สายลีนลดไขมัน คนแพ้แลคโตส และผู้ที่ต้องการโปรตีนสูงพิเศษแบบน้ำตาล 0 กรัม', '3690.00', '11-1-08463-5-0114', '4.9', 1960, '53 เซิร์ฟวิ่ง', '5 lbs (2.27 kg)', 'สายลีนลดไขมัน คนแพ้แลคโตส และผู้ที่ต้องการโปรตีนสูงพิเศษแบบน้ำตาล 0 กรัม', 'ผสม 1 ช้อนตวงกับน้ำเย็น 250-300 มล. หลังออกกำลังกายทันที หรือดื่มเสริมระหว่างวัน', 'fat-loss', 'โปรตีน 30g น้ำตาล 0g', 1, '/images/products/baam-iso-absolute-zero.webp', '[\"เวย์ไอโซเลทโปรตีนสูง 30g ต่อช้อน\",\"น้ำตาล 0g ไขมัน 0g คาร์บต่ำมาก\",\"BCAA 6.9g และ Glutamine 5.1g\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-mass-soy', 'Baam!! Mass Soy XXXXL Plant Gainer', 'แบม แมส ซอย เอ็กซ์เอ็กซ์เอ็กซ์แอล โปรตีนถั่วเหลืองเพิ่มน้ำหนัก (20 ปอนด์)', 'Baam!! (Fitwhey)', 'plant-protein', 'Plant Mass Gainer', '2025.00', 50, 'คนผอมที่แพ้นมวัวหรือกินเวย์แล้วสิวขึ้น แต่อยากเพิ่มน้ำหนักและสร้างมวลกล้ามเนื้อ', '2390.00', '11-1-08463-6-0020', '4.8', 1090, '150 ช้อน', '20 lbs (9.07 kg)', 'คนผอมที่แพ้นมวัวหรือกินเวย์แล้วสิวขึ้น แต่อยากเพิ่มน้ำหนักและสร้างมวลกล้ามเนื้อ', 'ผสม 2-3 ช้อนตวงกับน้ำเย็นหรือนมถั่วเหลือง 350 มล. ดื่มหลังออกกำลังกายและระหว่างมื้อ', 'muscle-gain', 'แมสเกนเนอร์จากพืช 20 ปอนด์', 1, '/images/products/baam-mass-soy.webp', '[\"โปรตีนถั่วเหลือง Non-GMO คุณภาพสูง 39g\",\"เสริมวิตามินและแร่ธาตุ 18 ชนิด ไร้นมวัว\",\"น้ำตาล 0g พลังงานสูงคุ้มค่าในถัง 20 ปอนด์\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-my-isosoy', 'Baam!! 100% My Iso-Soy (Fitwhey)', 'แบม 100% มาย ไอโซ-ซอย โปรตีนถั่วเหลืองไอโซเลท (เครือ Fitwhey)', 'Baam!! (Fitwhey)', 'plant-protein', 'Soy Protein Isolate', '1390.00', 50, 'ผู้ที่แพ้นมวัว, ผู้ทานมังสวิรัติ เจ วีแกน, ผู้ที่ต้องการลีนไขมันราคาประหยัด', '1650.00', '10-3-08829-1-0048', '4.8', 2150, '65 เซิร์ฟวิ่ง', '5 lbs (2.27 kg)', 'ผู้ที่แพ้นมวัว, ผู้ทานมังสวิรัติ เจ วีแกน, ผู้ที่ต้องการลีนไขมันราคาประหยัด', 'ผสม 1 ช้อนตวงกับน้ำเย็นหรือนมถั่วเหลือง 250 มล. ดื่มหลังออกกำลังกายหรือแทรกระหว่างมื้อ', 'fat-loss', 'ไอโซ-ซอย ขายดีอันดับ 1 Fitwhey', 1, '/images/products/baam-iso-soy.webp', '[\"โปรตีนถั่วเหลืองบริสุทธิ์ 27g ต่อช้อน\",\"น้ำตาล 0g ไขมัน 0g\",\"พลังงานเพียง 110 kcal\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-my-whey', 'Baam!! 100% My Whey Protein Concentrate', 'แบม 100% มาย เวย์โปรตีน คอนเซนเทรต (เครือ Fitwhey)', 'Baam!! (Fitwhey)', 'whey', 'Whey Concentrate (WPC)', '1650.00', 24, 'ผู้เริ่มต้นเล่นเวท, คนที่ต้องการโปรตีนเสริมในราคาประหยัดที่สุด', '1950.00', '10-3-08829-1-0045', '4.8', 3240, '68 เซิร์ฟวิ่ง', '5 lbs (2.27 kg)', 'ผู้เริ่มต้นเล่นเวท, คนที่ต้องการโปรตีนเสริมในราคาประหยัดที่สุด', 'ผสม 1 ช้อนตวงกับน้ำเย็น 250 มล. หลังออกกำลังกายทันที หรือระหว่างมื้ออาหาร', 'muscle-gain', 'ยอดขายอันดับ 1 ใน Fitwhey', 1, '/images/products/baam-my-whey-max.webp', '[\"โปรตีน 25g ต่อช้อน\",\"BCAA 5.5g\",\"รสชาติดื่มง่าย ละลายน้ำไว\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-ultra-mass', 'Baam!! Ultra Mass High-Calorie Gainer', 'แบม อัลตร้า แมส เกนเนอร์เพิ่มน้ำหนักสูตรพลังงานสูง (20 ปอนด์)', 'Baam!! (Fitwhey)', 'whey', 'Mass Gainer', '2800.00', 50, 'คนผอมมากที่กินอาหารมื้อหลักได้น้อย ต้องการพลังงานรวมสูงเพื่อเพิ่มน้ำหนักและมวลกล้าม', '3250.00', '11-1-08463-6-0007', '4.8', 1680, '151 ช้อน', '20 lbs (9.07 kg)', 'คนผอมมากที่กินอาหารมื้อหลักได้น้อย ต้องการพลังงานรวมสูงเพื่อเพิ่มน้ำหนักและมวลกล้าม', 'ผสม 2-3 ช้อนตวงกับน้ำเย็นหรือนม 350-450 มล. ดื่มหลังซ้อมและระหว่างมื้ออาหาร', 'muscle-gain', 'ถังใหญ่ 20 ปอนด์ เพิ่มน้ำหนักไว', 1, '/images/products/baam-ultra-mass.webp', '[\"พลังงานรวมสูงถึง 36,250 Kcal ต่อถัง\",\"เสริมวิตามินและแร่ธาตุ 18 ชนิด\",\"รสชาติดื่มง่าย ไม่ฝืดคอ\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-vitc-500', 'Baam!! Vitamin C 500mg Coated Tablets', 'แบม วิตามินซี 500 มก. เม็ดเคลือบฟิล์ม (120 เม็ด)', 'Baam!! (Fitwhey)', 'vitamin-zinc', 'Vitamin C', '650.00', 50, 'ผู้ที่ออกกำลังกายเป็นประจำ พักผ่อนน้อย ต้องการเสริมภูมิคุ้มกันและการสร้างคอลลาเจนทุกวัน', '790.00', '11-1-08463-5-0269', '4.8', 1490, '120 วัน', '120 เม็ด', 'ผู้ที่ออกกำลังกายเป็นประจำ พักผ่อนน้อย ต้องการเสริมภูมิคุ้มกันและการสร้างคอลลาเจนทุกวัน', 'รับประทานวันละ 1-2 เม็ด พร้อมมื้ออาหารเช้าหรือกลางวัน', 'general-health', 'ผ่านการตรวจแล็บ 120 เม็ด', 1, '/images/products/baam-vitc-500.webp', '[\"วิตามินซี 500mg ต่อเม็ด ปริมาณเหมาะสมต่อการดูดซึม\",\"เม็ดเคลือบฟิล์มกลืนง่าย ไม่กัดกระเพาะ\",\"กระปุกใหญ่ 120 เม็ด ทานได้นาน 2-4 เดือน\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-baam-zma', 'Baam!! ZMA (Zinc Magnesium Aspartate) (Fitwhey)', 'แบม ซีเอ็มเอ (ซิงค์ + แมกนีเซียม + บี6) 90 แคปซูล (เครือ Fitwhey)', 'Baam!! (Fitwhey)', 'vitamin-zinc', 'Zinc & ZMA (Fitwhey)', '790.00', 50, 'นักกีฬาที่ซ้อมหนัก พักผ่อนน้อย ต้องการหลับลึกเพื่อฟื้นฟูกล้ามเนื้อและฮอร์โมนเพศชาย', '950.00', '10-3-08829-1-0062', '4.9', 1680, '30 วัน', '90 แคปซูล', 'นักกีฬาที่ซ้อมหนัก พักผ่อนน้อย ต้องการหลับลึกเพื่อฟื้นฟูกล้ามเนื้อและฮอร์โมนเพศชาย', 'รับประทาน 3 แคปซูลก่อนนอน 30-60 นาที (ขณะท้องว่าง หลีกเลี่ยงการทานพร้อมแคลเซียม)', 'recovery', 'ซิงค์และซีเอ็มเอขายดี Fitwhey', 1, '/images/products/baam-zma.png', '[\"Zinc Monomethionine 30mg\",\"Magnesium Aspartate 450mg\",\"Vitamin B6 10.5mg ช่วยดูดซึม\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-blackmores-biozinc', 'Blackmores Bio Zinc Plus A, B6 & Manganese', 'แบลคมอร์ส ไบโอ ซิงค์ พลัส วิตามินเอ บี6 และแมงกานีส (90 เม็ด)', 'Blackmores', 'vitamin-zinc', 'Zinc Supplement', '450.00', 50, 'ทุกคนที่ต้องการเสริมภูมิคุ้มกัน ลดการอักเสบของผิวหนังและสิว บำรุงเส้นผมและเล็บ', '520.00', '10-3-08338-1-0009', '4.9', 3820, '90 วัน', '90 เม็ด', 'ทุกคนที่ต้องการเสริมภูมิคุ้มกัน ลดการอักเสบของผิวหนังและสิว บำรุงเส้นผมและเล็บ', 'รับประทานวันละ 1 เม็ด พร้อมอาหารมื้อใดก็ได้', 'general-health', 'ซิงค์มาตรฐานการแพทย์สากล', 1, '/images/products/blackmores-zinc.jpg', '[\"Zinc Amino Acid Chelate\",\"วิตามินเอและบี6 ส่งเสริมการดูดซึม\",\"ลดอาการอ่อนเพลีย\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-cellucor-c4', 'Cellucor C4 Original Pre-Workout', 'เซลลูคอร์ ซีโฟร์ ออริจินัล พรีเวิร์กเอาต์ (30 เซิร์ฟวิ่ง)', 'Cellucor', 'pre-workout', 'Classic High-Energy', '1290.00', 50, 'ผู้ที่ต้องการความตื่นตัว สมาธิ และพลังยกเวทในระดับที่พอเหมาะกำลังดี', '1490.00', '10-3-08829-1-0058', '4.9', 1540, '30 เซิร์ฟวิ่ง', '195 กรัม', 'ผู้ที่ต้องการความตื่นตัว สมาธิ และพลังยกเวทในระดับที่พอเหมาะกำลังดี', 'ชง 1 ช้อนตวงกับน้ำเย็น 200 มล. ดื่มก่อนออกกำลังกาย 20-30 นาที', 'strength', 'พรีเวิร์กเอาต์ยอดนิยมอันดับ 1', 1, '/images/products/c4-preworkout.png', '[\"CarnoSyn Beta-Alanine 1.6g\",\"คาเฟอีน 150mg เสริมสมาธิ\",\"Nitrate ปั๊มกล้ามแน่น\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-dymatize-iso100', 'Dymatize ISO100 Hydrolyzed 100% Whey Isolate', 'ไดมาไทซ์ ไอโซ 100 ไฮโดรไลซ์ เวย์ไอโซเลท (5 ปอนด์)', 'Dymatize', 'whey', 'Hydrolyzed & Isolate (WPH/WPI)', '2890.00', 11, 'คนแพ้นมวัว, ผู้ที่กำลังไดเอทตัดไขมัน (Cutting), นักกีฬาที่ต้องการดูดซึมเร็วที่สุด', '3250.00', '10-3-08829-1-0056', '4.9', 890, '76 เซิร์ฟวิ่ง', '5 lbs (2.3 kg)', 'คนแพ้นมวัว, ผู้ที่กำลังไดเอทตัดไขมัน (Cutting), นักกีฬาที่ต้องการดูดซึมเร็วที่สุด', 'ผสม 1 ช้อนกับน้ำเย็นหลังฝึกซ้อมทันที ดูดซึมเข้ากล้ามเนื้อใน 15 นาที', 'fat-loss', 'ดูดซึมไวที่สุด / ไร้แลคโตส', 1, '/images/products/dymatize-iso100.png', '[\"โปรตีน 25g ไขมัน 0g น้ำตาล 0g\",\"Hydrolyzed โมเลกุลเล็ก\",\"ปราศจากกลูเตนและแลคโตส\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-evogen-stimfree', 'Evogen EVP-3D Stim-Free Pump Pre-Workout', 'อีโวเจน อีวีพี ทรีดี พรีเวิร์กเอาต์สูตรไม่มีคาเฟอีน (ซ้อมรอบค่ำ)', 'Evogen', 'pre-workout', 'Stim-Free (Non-Caffeine)', '1690.00', 50, 'คนที่ซ้อมเวทหลังเลิกงานช่วงค่ำ, คนที่ไวต่อคาเฟอีนใจสั่นง่าย, หรือคนที่ดื่มกาแฟช่วงกลางวันมาแล้ว', '1990.00', '10-3-08829-5-0089', '4.8', 420, '30 เซิร์ฟวิ่ง', '420 กรัม', 'คนที่ซ้อมเวทหลังเลิกงานช่วงค่ำ, คนที่ไวต่อคาเฟอีนใจสั่นง่าย, หรือคนที่ดื่มกาแฟช่วงกลางวันมาแล้ว', 'ชง 1 ช้อนกับน้ำเย็นก่อนออกกำลังกาย 20 นาที ซ้อมเสร็จกลับบ้านนอนหลับสนิท', 'endurance', 'ไร้คาเฟอีน ไม่ใจสั่น นอนหลับสบาย', 1, '/images/products/evogen-stimfree.png', '[\"L-Citrulline 6,000mg ปั๊มกล้ามแน่น\",\"Beta-Alanine 3,200mg\",\"NO3-T Arginine Nitrate\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-fw-astaxanthin', 'Fitwhey Astaxanthin 6mg + CoQ10', 'ฟิตเวย์ แอสตาแซนธิน 6 มก. ผสมโคเอนไซม์คิวเทน (30 ซอฟต์เจล)', 'Fitwhey Supplements', 'vitamin-zinc', 'Antioxidant & Cellular Health', '265.00', 50, 'นักกีฬาที่ซ้อมกลางแจ้งหรือซ้อมหนัก ต้องการลดความเครียดออกซิเดชัน ฟื้นฟูเซลล์และบำรุงผิว', '350.00', '11-1-08463-6-0013', '4.9', 1840, '30 วัน', '30 ซอฟต์เจล', 'นักกีฬาที่ซ้อมกลางแจ้งหรือซ้อมหนัก ต้องการลดความเครียดออกซิเดชัน ฟื้นฟูเซลล์และบำรุงผิว', 'รับประทานวันละ 1 ซอฟต์เจล พร้อมอาหารที่มีไขมันดีเพื่อการดูดซึมสูงสุด', 'general-health', 'Astaxanthin 6mg + CoQ10', 1, '/images/products/fw-astaxanthin-coq10.webp', '[\"Astaxanthin 6mg ต้านอนุมูลอิสระประสิทธิภาพสูง\",\"เสริม CoQ10 สนับสนุนพลังงานระดับเซลล์และหัวใจ\",\"ซอฟต์เจลกลิ่นสตรอว์เบอร์รีทานง่าย\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-fw-super-omega3', 'Fitwhey Super Omega-3 Fish Oil 1000mg + Vitamin E', 'ฟิตเวย์ ซุปเปอร์ โอเมก้า-3 น้ำมันปลาเข้มข้น 1,000 มก. กลิ่นเลมอน (75 ซอฟต์เจล)', 'Fitwhey Supplements', 'fish-oil', 'Concentrated Omega-3', '460.00', 42, 'ผู้ที่ต้องการโอเมก้า-3 เข้มข้นดูแลข้อต่อ สมอง และหัวใจ พร้อมกลิ่นเลมอนลดกลิ่นคาวปลา', '550.00', '11-1-08463-5-0267', '4.9', 2110, '25 วัน (75 ซอฟต์เจล)', '75 ซอฟต์เจล', 'ผู้ที่ต้องการโอเมก้า-3 เข้มข้นดูแลข้อต่อ สมอง และหัวใจ พร้อมกลิ่นเลมอนลดกลิ่นคาวปลา', 'รับประทานครั้งละ 1-3 ซอฟต์เจล พร้อมมื้ออาหารเป็นประจำทุกวัน', 'recovery', 'กลิ่นเลมอนไม่คาว 75 ซอฟต์เจล', 1, '/images/products/fw-super-omega3.png', '[\"น้ำมันปลาเข้มข้น 1,000mg ต่อซอฟต์เจล พร้อม Vitamin E\",\"แต่งกลิ่นเลมอนธรรมชาติ ลดอาการเรอคาวปลา\",\"มาตรฐานการผลิต ISO 22000 ปลอดโลหะหนัก\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-fw-zinc-b3', 'Fitwhey Zinc 15mg + Vitamin B3', 'ฟิตเวย์ ซิงค์ 15 มก. ผสมวิตามินบี 3 (30 แคปซูล)', 'Fitwhey Supplements', 'vitamin-zinc', 'Zinc & Vitamin B3', '200.00', 50, 'ผู้ที่ต้องการเสริมภูมิคุ้มกัน ดูแลปัญหาผิวมัน สิวอักเสบ เส้นผม และสมดุลฮอร์โมนในราคาเข้าถึงง่าย', '260.00', '11-1-08463-5-0171', '4.9', 2260, '30 วัน', '30 แคปซูล', 'ผู้ที่ต้องการเสริมภูมิคุ้มกัน ดูแลปัญหาผิวมัน สิวอักเสบ เส้นผม และสมดุลฮอร์โมนในราคาเข้าถึงง่าย', 'รับประทานวันละ 1 แคปซูล พร้อมมื้ออาหารเช้าหรือเย็น', 'general-health', 'ซิงค์ + บี3 สุดคุ้ม Fitwhey', 1, '/images/products/fw-zinc-b3.webp', '[\"Zinc 15mg ปริมาณเต็มโดสต่อวัน\",\"Vitamin B3 (Niacinamide) 10mg ดูแลผิวและระบบเผาผลาญ\",\"แคปซูลกลืนง่าย ไม่ระคายเคืองกระเพาะ\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-kaged-creatine-hcl', 'Kaged Muscle Creatine HCl', 'เคจด์ มัสเซิล ครีเอทีน ไฮโดรคลอไรด์ (สูตรดูดซึมไว ไม่บวมน้ำ)', 'Kaged Muscle', 'creatine', 'Creatine HCl', '1350.00', 50, 'คนที่มีปัญหาท้องอืดจากครีเอทีนทั่วไป หรือนักกีฬาที่คุมน้ำหนักตัวเข้มงวด', '1590.00', '10-3-32458-5-0014', '4.8', 540, '75 เซิร์ฟวิ่ง', '56.25 กรัม', 'คนที่มีปัญหาท้องอืดจากครีเอทีนทั่วไป หรือนักกีฬาที่คุมน้ำหนักตัวเข้มงวด', 'รับประทาน 1-2 สกู๊ปเล็ก (750mg ต่อสกู๊ป) ผสมน้ำก่อนหรือหลังซ้อม ไม่ต้องโหลด', 'strength', 'ไม่ต้องโหลด / ไม่ทำให้บวมน้ำ', 1, '/images/products/kaged-creatine-hcl.png', '[\"ละลายน้ำไวกว่าสูตรเดิม 38 เท่า\",\"ใช้ปริมาณน้อยกว่าแต่ดูดซึมเต็มที่\",\"ปราศจากอาการไม่สบายท้อง\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-mega-omega3', 'Mega We Care Maxx Omega 3 (High Concentration)', 'เมก้า วี แคร์ แมกซ์ โอเมก้า 3 สูตรเข้มข้นพิเศษ EPA สูง (60 แคปซูล)', 'Mega We Care', 'fish-oil', 'High Concentration Omega-3', '690.00', 50, 'ผู้ที่ต้องการลดการอักเสบของกล้ามเนื้อและข้อต่ออย่างรวดเร็วด้วย EPA เข้มข้น', '820.00', '11-1-32732-1-0730', '4.9', 1640, '60 แคปซูล', '60 แคปซูล', 'ผู้ที่ต้องการลดการอักเสบของกล้ามเนื้อและข้อต่ออย่างรวดเร็วด้วย EPA เข้มข้น', 'รับประทานวันละ 1 แคปซูล พร้อมอาหารมื้อใดก็ได้', 'recovery', 'EPA 350mg / DHA 250mg เข้มข้น', 1, '/images/products/mega-omega3.jpg', '[\"ความเข้มข้นสูงกว่าน้ำมันปลาทั่วไป 2 เท่า\",\"มาตรฐานเกรดยา Pharmaceutical Grade\",\"ลดการสะสมไตรกลีเซอไรด์ในเลือด\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-muscletech-creatine', 'MuscleTech Platinum 100% Creatine', 'มัสเซิลเทค แพลตตินัม ครีเอทีน โมโนไฮเดรต (400g)', 'MuscleTech', 'creatine', 'Creatine Monohydrate', '890.00', 50, 'ผู้ที่ต้องการครีเอทีนมาตรฐานระดับแชมป์ งานวิจัยทางคลินิกรองรับ', '1090.00', '10-3-02947-1-0021', '4.9', 2310, '80 เซิร์ฟวิ่ง', '400 กรัม', 'ผู้ที่ต้องการครีเอทีนมาตรฐานระดับแชมป์ งานวิจัยทางคลินิกรองรับ', 'ตัก 1 ช้อน (5g) ผสมเครื่องดื่ม ดื่มวันละครั้งสม่ำเสมอทุกวัน', 'strength', 'ยอดขายอันดับ 1 ทั่วโลก', 1, '/images/products/muscletech-creatine.jpg', '[\"Micronized 100% ละลายน้ำง่าย\",\"เพิ่มพละกำลัง 1RM ภายใน 2 สัปดาห์\",\"ปลอดภัยต่อไตในคนปกติ\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-mutant-mass', 'Mutant Mass Gainer', 'มิวแทนท์ แมส เกนเนอร์ สูตรเพิ่มน้ำหนักและมวลกล้าม (5 ปอนด์)', 'Mutant', 'whey', 'Mass Gainer', '1990.00', 50, 'คนผอม น้ำหนักขึ้นยาก (Hardgainer), นักกีฬาที่ใช้พลังงานสูงมาก', '2350.00', '10-3-08829-1-0034', '4.8', 920, '16 มื้อยักษ์', '5 lbs (2.27 kg)', 'คนผอม น้ำหนักขึ้นยาก (Hardgainer), นักกีฬาที่ใช้พลังงานสูงมาก', 'แบ่งรับประทานวันละ 2 ครั้ง ครั้งละ 2 ช้อน หลังออกกำลังกายและก่อนนอน', 'muscle-gain', 'เพิ่มน้ำหนักตัวและกล้ามเนื้อ', 1, '/images/products/mutant-mass.png', '[\"1,100 แคลอรีต่อมื้อ\",\"โปรตีนมัลติสเตจ 56g\",\"คาร์โบไฮเดรตเชิงซ้อน 192g\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-on-fishoil', 'Optimum Nutrition Fish Oil Enteric-Coated', 'ออพติมัม น้ำมันปลาโอเมก้า-3 แคปซูลพิเศษไม่เหม็นคาว (100 ซอฟต์เจล)', 'Optimum Nutrition', 'fish-oil', 'Enteric-Coated Omega-3', '790.00', 50, 'คนเล่นเวทที่มีอาการปวดข้อต่อ, ผู้ที่ต้องการดูแลระบบหลอดเลือดและหัวใจ, คนที่ไม่ชอบกลิ่นคาวปลา', '950.00', '10-3-23348-1-0012', '4.9', 950, '100 ซอฟต์เจล', '100 Softgels', 'คนเล่นเวทที่มีอาการปวดข้อต่อ, ผู้ที่ต้องการดูแลระบบหลอดเลือดและหัวใจ, คนที่ไม่ชอบกลิ่นคาวปลา', 'รับประทานครั้งละ 1 ซอฟต์เจล วันละ 1-2 ครั้ง พร้อมมื้ออาหาร', 'recovery', 'Enteric-Coated ไม่ตีขึ้นคอ', 1, '/images/products/on-fish-oil.png', '[\"EPA 180mg / DHA 120mg ต่อเม็ด\",\"แคปซูลสลายตัวในลำไส้ ไร้กลิ่นคาว\",\"ผ่านการสกัดบริสุทธิ์ไร้สารปรอท\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-on-gold-whey', 'Optimum Nutrition Gold Standard 100% Whey', 'ออพติมัม โกลด์ สแตนดาร์ด เวย์โปรตีนเบลนด์ (5 ปอนด์)', 'Optimum Nutrition', 'whey', 'Whey Blend (WPI + WPC)', '2490.00', 18, 'ผู้ที่ต้องการเพิ่มกล้ามเนื้อระดับพรีเมียม มาตรฐานสากลโลก', '2890.00', '10-3-23348-1-0070', '4.9', 1420, '74 เซิร์ฟวิ่ง', '5 lbs (2.27 kg)', 'ผู้ที่ต้องการเพิ่มกล้ามเนื้อระดับพรีเมียม มาตรฐานสากลโลก', 'ผสม 1 ช้อนกับน้ำเย็น 200-250 มล. หลังซ้อม หรือดื่มเสริมมื้อเช้า', 'muscle-gain', 'มาตรฐานระดับโลก', 1, '/images/products/on-gold-whey.png', '[\"โปรตีน 24g ต่อช้อน\",\"กลูตามีน 4g\",\"เอนไซม์ช่วยย่อย Aminogen\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-on-optimen', 'Optimum Nutrition Opti-Men Multi-Vitamin', 'ออพติมัม ออปติ-เมน วิตามินรวมแร่ธาตุสำหรับนักกีฬา (90 เม็ด)', 'Optimum Nutrition', 'vitamin-zinc', 'Sports Multivitamin', '1190.00', 50, 'ผู้ชายที่ออกกำลังกายหนัก ต้องการเติมเต็มสารอาหารรองให้ครบถ้วนในเม็ดเดียว', '1390.00', '10-3-23348-1-0035', '4.8', 1290, '30 วัน', '90 เม็ด', 'ผู้ชายที่ออกกำลังกายหนัก ต้องการเติมเต็มสารอาหารรองให้ครบถ้วนในเม็ดเดียว', 'รับประทานวันละ 3 เม็ด พร้อมมื้ออาหารเช้าหรือเที่ยง', 'general-health', 'สารอาหารจำเป็นกว่า 75 ชนิด', 1, '/images/products/on-optimen.png', '[\"วิตามินและแร่ธาตุจำเป็นครบทุกตัว\",\"Amino-Blend กรดอะมิโน 8 ชนิด\",\"Phyto-Blend สารต้านอนุมูลอิสระ\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-plantae-complete', 'Plantae Complete Plant Protein 5 Plants', 'แพลนเต้ คอมพลีท แพลนท์ โปรตีน พืช 5 ชนิด รสช็อกโกแลต (1,000g)', 'Plantae', 'plant-protein', 'Multi-Plant Blend', '1790.00', 31, 'ผู้รักสุขภาพ ทานอาหารแพลนท์เบส คนรักสิ่งแวดล้อม และผู้ที่ต้องการรสชาติพรีเมียมดื่มง่าย', '2090.00', '10-1-05758-5-0021', '4.9', 1840, '30 เซิร์ฟวิ่ง', '1,000 กรัม', 'ผู้รักสุขภาพ ทานอาหารแพลนท์เบส คนรักสิ่งแวดล้อม และผู้ที่ต้องการรสชาติพรีเมียมดื่มง่าย', 'ชง 2 ช้อนกับน้ำเย็น 300 มล. ดื่มตอนเช้าเพื่อเริ่มต้นวัน หรือหลังออกกำลังกาย', 'general-health', 'โปรตีนพืชพรีเมียมอันดับ 1', 1, '/images/products/plantae-plant-protein.png', '[\"โปรตีนพืชสูง 30g ต่อมื้อ\",\"กรดอะมิโนครบ 9 ชนิด\",\"ไม่สากคอ ย่อยง่าย ไร้สารก่อภูมิแพ้\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-redcon1-totalwar', 'Redcon1 Total War High-Stim Pre-Workout', 'เรดคอนวัน โททัล วอร์ พรีเวิร์กเอาต์สูตรฮาร์ดคอร์ (30 เซิร์ฟวิ่ง)', 'Redcon1', 'pre-workout', 'Hardcore High-Stim', '1490.00', 50, 'สายยกหนัก คนที่ดื้อคาเฟอีน และต้องการพลังงานและความเข้มข้นขั้นสุด', '1750.00', '10-3-22864-5-0035', '4.9', 880, '30 เซิร์ฟวิ่ง', '441 กรัม', 'สายยกหนัก คนที่ดื้อคาเฟอีน และต้องการพลังงานและความเข้มข้นขั้นสุด', 'เริ่มจากครึ่งช้อนเพื่อทดสอบการตอบสนอง ก่อนซ้อม 30 นาที (ห้ามดื่มก่อนนอน 6 ชม.)', 'strength', 'คาเฟอีนเข้มข้น 320mg', 1, '/images/products/total-war.png', '[\"Citrulline Malate 6g เต็มโดส\",\"Beta-Alanine 3.2g\",\"คาเฟอีน 2 ฟอร์มออกฤทธิ์ต่อเนื่อง\"]', '2026-11-21 20:23:09');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-bcaa-6500', 'Vitaxtrong 100% Pure BCAA 6500 (2:1:1)', 'ไวต้าสตรอง 100% เพียว บีซีเอเอ 6500 อัตราส่วน 2:1:1 (330 กรัม)', 'Vitaxtrong (Fitwhey)', 'pre-workout', 'Pure BCAA 2:1:1', '825.00', 50, 'ผู้ที่ออกกำลังกายตอนเช้าแบบท้องว่าง (Fasted Cardio) หรืออยู่ในช่วงลดไขมันคุมแคลอรีเข้มงวด', '990.00', '11-1-08463-5-0003', '4.8', 1120, '50 เซิร์ฟวิ่ง', '330 กรัม', 'ผู้ที่ออกกำลังกายตอนเช้าแบบท้องว่าง (Fasted Cardio) หรืออยู่ในช่วงลดไขมันคุมแคลอรีเข้มงวด', 'ผสม 1 ช้อนตวง (6.5g) กับน้ำเย็นหรือเครื่องดื่มเกลือแร่ ดื่มก่อนหรือระหว่างซ้อม', 'recovery', 'อัตราส่วนงานวิจัย 2:1:1', 1, '/images/products/vx-bcaa-6500.png', '[\"BCAA บริสุทธิ์ 6.5g ต่อช้อน ไร้สี ไร้น้ำตาล\",\"อัตราส่วน Leucine:Isoleucine:Valine 2:1:1 ตามงานวิจัย\",\"ชงผสมกับพรีเวิร์กเอาต์หรือเวย์ได้ทันที\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-iso-pro', 'Vitaxtrong 100% ISO-PRO Hydrolyzed Isolate', 'ไวต้าสตรอง ไอโซ-โปร ไฮโดรไลซ์ เวย์ไอโซเลท (8 ปอนด์)', 'Vitaxtrong (Fitwhey)', 'whey', 'Hydrolyzed Isolate (WPH/WPI)', '4950.00', 28, 'ผู้ที่สร้างกล้ามเนื้อแบบลีนต่อเนื่อง ต้องการไซส์คุ้มค่าและคาร์โบไฮเดรตต่ำเพียง 1 กรัม', '5490.00', '11-1-08463-5-0082', '4.9', 1520, '110 เซิร์ฟวิ่ง', '8 lbs (3.63 kg)', 'ผู้ที่สร้างกล้ามเนื้อแบบลีนต่อเนื่อง ต้องการไซส์คุ้มค่าและคาร์โบไฮเดรตต่ำเพียง 1 กรัม', 'ผสม 1 ช้อนตวงกับน้ำเย็น 200-250 มล. หลังออกกำลังกาย หรือช่วงเช้าหลังตื่นนอน', 'fat-loss', 'ไซส์คุ้ม 8 ปอนด์ คาร์บ 1g', 1, '/images/products/vx-iso-pro.webp', '[\"โปรตีนจาก Hydrolyzed Whey 27g ต่อช้อน\",\"คาร์โบไฮเดรตเพียง 1g ไม่มีน้ำตาลและไขมัน\",\"ละลายไว ไม่จับตัวเป็นก้อน\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-mega-mass', 'Vitaxtrong Mega Mass Pro 1350', 'ไวต้าสตรอง เมก้า แมส โปร 1350 เกนเนอร์เพิ่มน้ำหนัก (12 ปอนด์)', 'Vitaxtrong (Fitwhey)', 'whey', 'Hardcore Mass Gainer', '1910.00', 50, 'สายเพิ่มน้ำหนักแบบฮาร์ดคอร์ คนเผาผลาญไวมาก และนักกีฬาที่ต้องการแคลอรีสูงต่อมื้อ', '2290.00', '11-1-08463-6-0002', '4.9', 2450, '16 มื้อเต็ม', '12 lbs (5.44 kg)', 'สายเพิ่มน้ำหนักแบบฮาร์ดคอร์ คนเผาผลาญไวมาก และนักกีฬาที่ต้องการแคลอรีสูงต่อมื้อ', 'แบ่งชงครั้งละ 1.5-2 ช้อนตวง วันละ 2 ครั้ง หลังออกกำลังกายและก่อนนอน', 'muscle-gain', 'พลังงาน 1,350+ Kcal ต่อมื้อ', 1, '/images/products/vx-mega-mass.webp', '[\"ให้พลังงาน 1,350+ แคลอรีต่อมื้อ\",\"โปรตีนแท้ 70g+ พร้อมกรดอะมิโนจำเป็น 9 ชนิด\",\"วิตามิน แร่ธาตุ และกรดอะมิโนรวม 38 ชนิด\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-omeflame', 'Vitaxtrong Omeflame X3000 Sports Omega-3', 'ไวต้าสตรอง โอเมเฟลม น้ำมันปลาเข้มข้นสูตรนักกีฬา 3,000 มก. (180 ซอฟต์เจล)', 'Vitaxtrong (Fitwhey)', 'fish-oil', 'Sports-Grade Omega-3', '840.00', 50, 'นักเวทเทรนนิ่งและนักกีฬาที่ซ้อมหนักมีอาการปวดข้อต่อ ต้องการ EPA/DHA เข้มข้นลดการอักเสบ', '990.00', '11-1-08463-2-0016', '4.9', 1380, '60 วัน (180 ซอฟต์เจล)', '180 ซอฟต์เจล', 'นักเวทเทรนนิ่งและนักกีฬาที่ซ้อมหนักมีอาการปวดข้อต่อ ต้องการ EPA/DHA เข้มข้นลดการอักเสบ', 'รับประทานวันละ 3 ซอฟต์เจล แบ่งทานพร้อมมื้ออาหารเช้า กลางวัน และเย็น', 'recovery', 'สูตรนักกีฬา 3,000mg / 180 เม็ด', 1, '/images/products/vx-omeflame.png', '[\"น้ำมันปลาเข้มข้นสูง 3,000mg ต่อหน่วยบริโภค\",\"เน้นลดการอักเสบข้อต่อและสนับสนุนการฟื้นตัวกล้ามเนื้อ\",\"กลิ่นเลมอนเนดทานง่าย คุ้มค่า 180 ซอฟต์เจล\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-pure-creatine', 'Vitaxtrong 100% Pure Creatine 5000', 'ไวต้าสตรอง 100% เพียว ครีเอทีน โมโนไฮเดรต (300 กรัม)', 'Vitaxtrong (Fitwhey)', 'creatine', 'Creatine Monohydrate', '375.00', 50, 'ผู้เริ่มต้นจนถึงนักกีฬาที่ต้องการครีเอทีนบริสุทธิ์ 100% ราคาจับต้องได้ง่ายที่สุด', '490.00', '11-1-08463-5-0001', '4.9', 2890, '60 เซิร์ฟวิ่ง', '300 กรัม', 'ผู้เริ่มต้นจนถึงนักกีฬาที่ต้องการครีเอทีนบริสุทธิ์ 100% ราคาจับต้องได้ง่ายที่สุด', 'ตัก 1 ช้อนตวง (5g) ผสมกับน้ำเปล่า เวย์โปรตีน หรือน้ำผลไม้ ดื่มวันละ 1 ครั้งต่อเนื่องทุกวัน', 'strength', 'ครีเอทีนราคาคุ้มค่า Fitwhey', 1, '/images/products/vx-pure-creatine.png', '[\"Creatine Monohydrate บริสุทธิ์ 5g ต่อช้อน\",\"ช่วยเพิ่มพลังงาน ATP และแรงยกสูงสุด\",\"ไม่มีรสชาติ ผสมร่วมกับเวย์หรือเครื่องดื่มอื่นง่าย\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-real-whey', 'Vitaxtrong 100% Real Whey Protein', 'ไวต้าสตรอง เรียล เวย์ โปรตีน เบลนด์ ถุงใหญ่คุ้มค่า (10 ปอนด์)', 'Vitaxtrong (Fitwhey)', 'whey', 'Whey Blend (WPI + WPC)', '4585.00', 50, 'ผู้ที่ดื่มเวย์ประจำทุกวัน ต้องการเวย์แท้ไม่เจือปนกรดอะมิโนในราคาต่อช้อนสุดคุ้ม', '5150.00', '11-1-08463-5-0105', '4.8', 2140, '132 เซิร์ฟวิ่ง', '10 lbs (4.54 kg)', 'ผู้ที่ดื่มเวย์ประจำทุกวัน ต้องการเวย์แท้ไม่เจือปนกรดอะมิโนในราคาต่อช้อนสุดคุ้ม', 'ผสม 1 ช้อนตวงกับน้ำเย็น 250 มล. ดื่มหลังออกกำลังกายและช่วงเช้า', 'muscle-gain', 'ไซส์ประหยัด 10 ปอนด์', 1, '/images/products/vx-real-whey.webp', '[\"โปรตีนแท้ 26g ต่อช้อน ไม่มี Amino Spiking\",\"Triple Micro-Filtered Whey คุณภาพสูง\",\"ชงง่าย รสชาติดี คุ้มค่าที่สุดในรุ่น\"]', '2026-11-26 23:24:40');
INSERT INTO `products` (`id`, `name`, `nameTH`, `brand`, `category`, `subCategory`, `price`, `stock`, `detail`, `originalPrice`, `fdaNumber`, `rating`, `reviewsCount`, `servings`, `size`, `suitableFor`, `howToUse`, `goal`, `badge`, `inStock`, `imageUrl`, `features`, `created_at`) VALUES ('prod-vx-xpush', 'Vitaxtrong X-PUSH Pre-Workout', 'ไวต้าสตรอง เอ็กซ์-พุช พรีเวิร์กเอาต์เพิ่มพละกำลัง (330 กรัม)', 'Vitaxtrong (Fitwhey)', 'pre-workout', 'High-Energy Pre-Workout', '1125.00', 7, 'ผู้ที่ต้องการความตื่นตัว แรงผลักดัน และโฟกัสเต็มพิกัดก่อนเข้ายิมยกเวทหรือคาร์ดิโอ', '1350.00', '11-1-08463-5-0210', '4.8', 940, '30 เซิร์ฟวิ่ง', '330 กรัม', 'ผู้ที่ต้องการความตื่นตัว แรงผลักดัน และโฟกัสเต็มพิกัดก่อนเข้ายิมยกเวทหรือคาร์ดิโอ', 'ผสม 1 ช้อนตวงกับน้ำเย็น 250 มล. ดื่มก่อนออกกำลังกาย 20-30 นาที', 'strength', 'พรีเวิร์กเอาต์สูตรเข้มข้น VX', 1, '/images/products/vx-xpush.webp', '[\"Beta-Alanine ชะลออาการล้าของกล้ามเนื้อ\",\"L-Citrulline + Arginine เพิ่มการสูบฉีดเลือด\",\"คาเฟอีนธรรมชาติจาก Green Coffee Bean และ Yerba Mate\"]', '2026-11-26 23:24:40');

-- --------------------------------------------------------
-- โครงสร้างตาราง: `orders`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` varchar(100) NOT NULL,
  `userId` int(11) DEFAULT NULL,
  `customerName` varchar(255) NOT NULL,
  `customerPhone` varchar(50) NOT NULL,
  `customerAddress` text NOT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `totalAmount` decimal(10,2) NOT NULL,
  `status` varchar(50) DEFAULT 'pending',
  `createdAt` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ข้อมูลสำหรับตาราง `orders`
